window.kbPageData["views/entry/k-5390be50d683de51"] = {"key":"entry/k-5390be50d683de51","state":{"route":"entry/k-5390be50d683de51"},"node":{"id":"k-5390be50d683de51","mode":"k","title":"轴对称的保距与保角","type":"原理与机制","domain":"数学","reading":"","intro":"","priority":100,"aliases":["轴对称保持对应线段长度和角度"],"qs":["江苏 2023 A类 行测#59"],"current":false,"candidates":true,"sources":[],"basisGroup":"","authority":null,"sourceOnly":false,"reviewSet":"单次条目","independentCount":1,"repeatPositions":0,"directorySummary":"图形沿一条直线翻折时，折痕上的点位置不变，对应线段等长，对应角相等。","review":{"definition":"图形沿一条直线翻折时，折痕上的点位置不变，对应线段等长，对应角相等。","explanation":"第59题中，沿AD翻折后，C落在AB上的C′，A和D位置不变，因此AC′=AC、DC′=DC，且∠AC′D仍为直角。由勾股定理得AC=6厘米，所以BC′=4厘米。设DC=x厘米，则BD=8−x厘米。在直角三角形BC′D中，由(8−x)²=4²+x²得x=3，因此BD=5厘米。以BD为底、AC为高，△ABD的面积为15平方厘米，对应A项。","references":[],"evidence":"若将纸片沿AD折叠，直角边AC恰好与斜边AB重叠","disposition":"独立词条","basis":"据原题和解析编释。"}},"questions":{"江苏 2023 A类 行测#59":{"paper":"江苏 2023 A类 行测","n":59,"mod":"数量关系","src":["22304fe4c340e19d7902.pdf",11],"asrc":["be17f9afe070cf13a0fb.pdf",17],"card":"9479a58ec9bdb0fae03bb9ad","links":[{"id":"k-5390be50d683de51","role":"解题依据","why":"折叠使C与图中的C′对应，从而得到对应线段相等，并保留折叠前的直角。"}]}},"terms":{},"references":{},"topics":[],"units":{"k-5390be50d683de51":[["江苏 2023 A类 行测#59"]]}};
